import { useState } from 'react';
import { Input } from '@/components/ui/input';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import MainHeading from '@/components/heading/MainHeading';
import GoalsTable from './programForm/GoalsTable';
import TechnicalCompetenciesTable from './programForm/technical_competencies/GoalsTable';

type GoalItem = { id: number; title: string };

const options = [{ label: 'اختر', value: '' }];

const trainingGoals: GoalItem[] = [
    { id: 1, title: 'بناء تطبيقات واجهة أمامية باستخدام React' },
    { id: 2, title: 'التعامل مع قواعد البيانات وإنشاء APIs' },
    { id: 3, title: 'اختبار وبناء تطبيقات متكاملة' },
    { id: 4, title: 'تحسين جودة الكود واكتشاف الأخطاء' },
    { id: 5, title: 'إنشاء مشروع التخرج التدريبي بنجاح' },
];

const practicalSkills: GoalItem[] = [
    { id: 1, title: 'إتقان بنية واجهة المستخدم' },
    { id: 2, title: 'التخطيط وإدارة المهام والأرقام' },
    { id: 3, title: 'استخدام الأدوات الحديثة بالتقنيات' },
    { id: 4, title: 'التعامل مع أدوات المراقبة والبيئات' },
    { id: 5, title: 'التعاون والعمل الجماعي التقني' },
];

export default function AddProgramForm() {
    const [programName, setProgramName] = useState('');
    const [programPrice, setProgramPrice] = useState('');
    const [programDuration, setProgramDuration] = useState('');

    return (
        <div className="mt-4  bg-white p-3 sm:p-4">
            <MainHeading text="تفاصيل البرنامج" className="mb-6" />

            <div className="grid grid-cols-1 gap-3 p-3 sm:grid-cols-2">
                <div>
                    <p className="mb-1 text-right text-sm font-medium text-primery-blue-900">اسم البرنامج</p>
                    <Input
                        value={programName}
                        onChange={(e) => setProgramName(e.target.value)}
                        placeholder="ادخل اسم البرنامج"
                        className="h-10 text-right"
                    />
                </div>
                <div>
                    <p className="mb-1 text-right text-sm font-medium text-primery-blue-900">القسم</p>
                    <CustomSelect
                        options={options}
                        value=""
                        onValueChange={() => undefined}
                        placeholder="اختر القسم"
                        width="w-full"
                    />
                </div>
                <div>
                    <p className="mb-1 text-right text-sm font-medium text-primery-blue-900">اجمالي المقاعد</p>
                    <Input
                        value={programPrice}
                        onChange={(e) => setProgramPrice(e.target.value)}
                        placeholder="ادخل عدد المقاعد في البرنامج"
                        className="h-10 text-right"
                    />
                </div>
                <div>
                    <p className="mb-1 text-right text-sm font-medium text-primery-blue-900">المده</p>
                    <Input
                        value={programDuration}
                        onChange={(e) => setProgramDuration(e.target.value)}
                        placeholder="8 اسابيع"
                        className="h-10 text-right"
                    />
                </div>
            </div>

            <GoalsTable title="الاهداف التدريبية" rows={trainingGoals} />
            <TechnicalCompetenciesTable title="المهارات العملية" rows={practicalSkills} />

            <div className="mt-6 flex flex-col-reverse gap-3 sm:flex-row sm:justify-start">
                <PrimaryButton className="min-w-[116px]">اضافة</PrimaryButton>
                <SecondaryButton className="min-w-[116px] bg-[#FBE2E2] text-[#C52E2E] hover:bg-[#f8d4d4]">
                    الغاء
                </SecondaryButton>
            </div>
        </div>
    );
}
