import { ColumnDef, Row } from '@tanstack/react-table';
import TrashIcon from '@/components/icons/TrashIcon';
import { useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import DeletePopup from '@/components/Popups/DeletePopup';
import { toast } from 'sonner';
import { Program } from '../../types/program.types';
import EyeIcon from '@/components/icons/marketing/EyeIcon';


// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<Program> }) => {
    const [showDeletePopup, setShowDeletePopup] = useState(false);
    const [showPreviewPopup, setShowPreviewPopup] = useState(false);

    const handleDelete = () => {
        setShowDeletePopup(true);
    };

    const handleCancel = () => {
        setShowDeletePopup(false);
    };

    const handleSuccess = () => {
        toast.error('تم حذف الوظيفه بنجاح');
        setShowDeletePopup(false);
        row.original.refreshTable?.();
    };
    const previewJob = () => {
        setShowPreviewPopup(true);
    };

    return (
        <>
            <div className="flex items-center gap-7">
                <button
                    onClick={previewJob}
                    className="text-primary hover:text-primary/80"
                >
                    <EyeIcon />
                </button>
                <button onClick={handleDelete}>
                    <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                </button>
            </div>


            {showDeletePopup && (
                <DeletePopup
                    open={showDeletePopup}
                    text="هل أنت متاكد أنك تريد حذف هذا البند"
                    endpoint={endpoints.career.delete + row.original.id}
                    handleCancel={handleCancel}
                    handleSuccess={handleSuccess}
                />
            )}
        </>
    );
};

export const columns: ColumnDef<Program>[] = [
    {
        accessorKey: 'name',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    اسم البند
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.name}
            </div>
        ),
    },
   

    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الاجراءات
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
